from z3 import *
import itertools

n = 21

# Create boolean variables for edges
edges = [[Bool(f'e_{i}_{j}') for j in range(n)] for i in range(n)]

s = Solver()

# Symmetry and no self-loops
for i in range(n):
    for j in range(n):
        if i == j:
            s.add(Not(edges[i][j]))
        elif i < j:
            s.add(edges[i][j] == edges[j][i])

# Condition 1: alpha(G) <= 4
for combo in itertools.combinations(range(n), 5):
    clause = Or([edges[i][j] for i, j in itertools.combinations(combo, 2)])
    s.add(clause)

# Minimum degree >= 5
for i in range(n):
    deg = Sum([If(edges[i][j], 1, 0) for j in range(n) if j != i])
    s.add(deg >= 5)

print("Solving...")
result = s.check()
print(result)

if result == sat:
    m = s.model()
    # Build adjacency matrix
    adj = [[False]*n for _ in range(n)]
    for i in range(n):
        for j in range(i+1, n):
            if is_true(m[edges[i][j]]):
                adj[i][j] = adj[j][i] = True

    # Print degrees
    degrees = [sum(adj[i]) for i in range(n)]
    print("Degrees:", degrees)
    print("Min degree:", min(degrees))

    # Check alpha(G) <= 4
    def is_independent(vertices):
        for i, j in itertools.combinations(vertices, 2):
            if adj[i][j]:
                return False
        return True

    max_independent = 0
    for r in range(5, n+1):
        found = False
        for combo in itertools.combinations(range(n), r):
            if is_independent(combo):
                max_independent = r
                found = True
                break
        if not found:
            break
    print("Max independent set size:", max_independent)

    # Check connectivity
    def is_connected(graph_adj):
        visited = [False]*n
        stack = [0]
        visited[0] = True
        while stack:
            v = stack.pop()
            for u in range(n):
                if graph_adj[v][u] and not visited[u]:
                    visited[u] = True
                    stack.append(u)
        return all(visited)

    # Check kappa(G) >= 4
    # For any set S of size <= 3, G-S should be connected
    kappa = n
    for r in range(1, 4):
        for S in itertools.combinations(range(n), r):
            # Build graph without S
            adj_minus_S = [[False]*n for _ in range(n)]
            for i in range(n):
                if i in S:
                    continue
                for j in range(n):
                    if j in S or i == j:
                        continue
                    adj_minus_S[i][j] = adj[i][j]
            if not is_connected(adj_minus_S):
                kappa = r
                print(f"Found separator of size {r}: {S}")
                break
        if kappa < n:
            break

    if kappa == n:
        # Check for r=0 (just connectivity)
        if is_connected(adj):
            kappa = n  # means >= 4
        else:
            kappa = 0

    print("Vertex connectivity:", kappa if kappa < n else ">= 4")

    # List edges
    edge_list = []
    for i in range(n):
        for j in range(i+1, n):
            if adj[i][j]:
                edge_list.append((i, j))
    print("Number of edges:", len(edge_list))
    print("Edges:", edge_list[:20], "...")

