def is_connected(adj_matrix, exclude=set()):
    remaining = [v for v in range(n) if v not in exclude]
    if len(remaining) <= 1:
        return True
    visited = set()
    stack = [remaining[0]]
    visited.add(remaining[0])
    while stack:
        v = stack.pop()
        for u in remaining:
            if adj_matrix[v][u] and u not in visited:
                visited.add(u)
                stack.append(u)
    return len(visited) == len(remaining)

